<?php
namespace Tests\Feature;
use App\Services\Borrowing\SupabaseBorrowingService;
use Illuminate\Support\Facades\Http;
use Mockery;
use Tests\TestCase;
final class BorrowingApiTest extends TestCase {
 private const ADMIN='11111111-1111-4111-8111-111111111111';
 private const STAFF='22222222-2222-4222-8222-222222222222';
 private const ROLE='33333333-3333-4333-8333-333333333333';
 protected function setUp():void{parent::setUp();config(['supabase.url'=>'https://example.supabase.co','supabase.publishable_key'=>'test-publishable-key','supabase.auth_user_timeout'=>10]);}
 private function fakeUser(string $id,string $role,array $permissions):void{Http::fake(['https://example.supabase.co/auth/v1/user'=>Http::response(['id'=>$id,'email'=>'test@example.test'],200),'https://example.supabase.co/rest/v1/profiles*'=>Http::response([['id'=>$id,'full_name'=>'Test','email'=>'test@example.test','status'=>'active']],200),'https://example.supabase.co/rest/v1/user_roles*'=>Http::response([['role_id'=>self::ROLE,'roles'=>['name'=>$role]]],200),'https://example.supabase.co/rest/v1/role_permissions*'=>Http::response(array_map(fn($p)=>['permissions'=>['name'=>$p]],$permissions),200)]);}
 public function test_staff_can_submit_a_borrow_request_through_authorized_service():void{$this->fakeUser(self::STAFF,'staff_sa',['borrowing.view','borrowing.request']);$service=Mockery::mock(SupabaseBorrowingService::class);$service->shouldReceive('createRequest')->once()->with('staff-token',Mockery::on(fn($d)=>count($d['items'])===1))->andReturn(['id'=>'44444444-4444-4444-8444-444444444444','status'=>'pending']);$this->app->instance(SupabaseBorrowingService::class,$service);$this->withToken('staff-token')->postJson('/api/v1/borrowing/requests',['expected_return_at'=>now()->addDays(3)->toIso8601String(),'items'=>[['item_id'=>'55555555-5555-4555-8555-555555555555','quantity'=>2]]])->assertCreated()->assertJsonPath('data.request.status','pending');}
 public function test_staff_cannot_review_borrowing_requests():void{$this->fakeUser(self::STAFF,'staff_sa',['borrowing.view','borrowing.request']);$service=Mockery::mock(SupabaseBorrowingService::class);$service->shouldNotReceive('reviewRequest');$this->app->instance(SupabaseBorrowingService::class,$service);$this->withToken('staff-token')->postJson('/api/v1/borrowing/requests/44444444-4444-4444-8444-444444444444/review',['decision'=>'approved'])->assertForbidden();}
 public function test_admin_can_review_a_pending_request():void{$this->fakeUser(self::ADMIN,'admin',['borrowing.view','borrowing.manage']);$service=Mockery::mock(SupabaseBorrowingService::class);$service->shouldReceive('reviewRequest')->once()->with('admin-token','44444444-4444-4444-8444-444444444444',Mockery::on(fn($d)=>$d['decision']==='approved'))->andReturn(['id'=>'44444444-4444-4444-8444-444444444444','status'=>'approved']);$this->app->instance(SupabaseBorrowingService::class,$service);$this->withToken('admin-token')->postJson('/api/v1/borrowing/requests/44444444-4444-4444-8444-444444444444/review',['decision'=>'approved'])->assertOk()->assertJsonPath('data.request.status','approved');}
 public function test_return_processing_requires_admin_permissions():void{$this->fakeUser(self::STAFF,'staff_sa',['borrowing.view','borrowing.return']);$service=Mockery::mock(SupabaseBorrowingService::class);$service->shouldNotReceive('processReturn');$this->app->instance(SupabaseBorrowingService::class,$service);$this->withToken('staff-token')->postJson('/api/v1/borrowing/records/44444444-4444-4444-8444-444444444444/returns',['items'=>[['item_id'=>'55555555-5555-4555-8555-555555555555','quantity'=>1,'condition'=>'good']]])->assertForbidden();}
}